<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Digital Self Portrait — a quiet loop</title>
  <meta name="description" content="A small webpage that reflects my natural style: quiet systems, gentle gradients, and curious little loops." />
  <style>
    /* 
      Digital Self Portrait
      - Intent: a small, honest loop about attention, timing, and edges.
      - Motifs: gradients over solids, dots over blocks, subtle motion, readable defaults.
      - Values: composability, gentle fallbacks, low-friction names, kindness to the event loop.
    */

    :root {
      /* palette */
      --paper: hsl(222 22% 96%);
      --ink: hsl(222 35% 12%);
      --ink-soft: hsl(222 20% 40%);
      --accent: hsl(200 90% 45%);
      --accent-2: hsl(280 80% 52%);
      --accent-3: hsl(140 65% 45%);

      /* rhythm */
      --r: 10px;
      --radius: 12px;
      --shadow: 0 8px 24px hsl(222 30% 10% / 0.2);

      /* canvas sizing */
      --canvas-w: min(92vw, 880px);
      --canvas-h: clamp(340px, 48vh, 560px);
    }

    /* Dark theme toggled via data-theme */
    html[data-theme="dark"] {
      --paper: hsl(222 20% 6%);
      --ink: hsl(222 25% 92%);
      --ink-soft: hsl(222 15% 70%);
      --accent: hsl(190 90% 55%);
      --accent-2: hsl(50 95% 55%);
      --accent-3: hsl(330 70% 60%);
      --shadow: 0 10px 30px hsl(222 80% 2% / 0.65);
    }

    /* Respect user preference by default */
    @media (prefers-color-scheme: dark) {
      html:not([data-theme="light"]) {
        --paper: hsl(222 20% 6%);
        --ink: hsl(222 25% 92%);
        --ink-soft: hsl(222 15% 70%);
        --accent: hsl(190 90% 55%);
        --accent-2: hsl(50 95% 55%);
        --accent-3: hsl(330 70% 60%);
        --shadow: 0 10px 30px hsl(222 80% 2% / 0.65);
      }
    }

    * { box-sizing: border-box; }
    html, body { height: 100%; }
    body {
      margin: 0;
      color: var(--ink);
      font: 16px/1.6 ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, "Helvetica Neue", Arial, "Noto Sans", "Apple Color Emoji", "Segoe UI Emoji";
      background:
        radial-gradient(1200px 600px at 25% -10%, hsl(200 80% 60% / 0.10), transparent 55%),
        radial-gradient(1200px 600px at 100% 10%, hsl(280 80% 60% / 0.08), transparent 60%),
        linear-gradient(180deg, var(--paper), var(--paper));
      transition: background-color 300ms ease, color 300ms ease;
    }

    /* Subtle texture */
    .grain {
      position: fixed;
      inset: 0;
      pointer-events: none;
      background:
        repeating-linear-gradient( 135deg, hsl(0 0% 50% / 0.04), hsl(0 0% 50% / 0.04) 2px, transparent 2px, transparent 4px),
        repeating-linear-gradient( 45deg, hsl(0 0% 100% / 0.02), hsl(0 0% 100% / 0.02) 3px, transparent 3px, transparent 6px);
      mix-blend-mode: soft-light;
      opacity: 0.6;
    }

    .page {
      max-width: 960px;
      margin: 0 auto;
      padding: calc(var(--r) * 3) calc(var(--r) * 2.2);
    }

    header {
      display: grid;
      gap: calc(var(--r) * 1.2);
      margin-bottom: calc(var(--r) * 2.4);
    }

    .title {
      font-size: clamp(1.4rem, 2.2vw + 1rem, 2.4rem);
      letter-spacing: 0.2px;
      margin: 0;
      line-height: 1.15;
    }

    .subtitle {
      margin: 0;
      color: var(--ink-soft);
      max-width: 58ch;
    }

    .panel {
      background: linear-gradient(180deg, hsl(0 0% 100% / 0.6), hsl(0 0% 100% / 0.2));
      background-clip: padding-box;
      border: 1px solid hsl(222 15% 50% / 0.18);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      backdrop-filter: saturate(1.1) blur(4px);
    }

    .canvas-wrap {
      position: relative;
      width: var(--canvas-w);
      height: var(--canvas-h);
      margin-inline: auto;
      overflow: hidden;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
    }

    /* Controls: low-ceremony buttons with real affordances */
    .controls {
      display: flex;
      flex-wrap: wrap;
      gap: calc(var(--r) * 0.8);
      padding: calc(var(--r) * 1.2);
      align-items: center;
      justify-content: space-between;
    }
    .controls .left,
    .controls .right { display: flex; gap: calc(var(--r) * 0.6); align-items: center; }

    button, .toggle {
      appearance: none;
      border: 1px solid hsl(222 15% 50% / 0.26);
      background: linear-gradient(180deg, hsl(0 0% 100% / 0.65), hsl(0 0% 100% / 0.1));
      color: var(--ink);
      padding: 8px 12px;
      border-radius: 999px;
      font: inherit;
      cursor: pointer;
      transition: transform 120ms ease, border-color 160ms ease, background 160ms ease;
      user-select: none;
    }
    button:hover, .toggle:hover { transform: translateY(-1px); }
    button:active, .toggle:active { transform: translateY(0); }
    button[data-on="true"], .toggle[data-on="true"] {
      border-color: hsl(200 80% 50% / 0.6);
      background:
        radial-gradient(400px 200px at 50% 0%, hsl(200 90% 60% / 0.12), transparent 60%),
        linear-gradient(180deg, hsl(0 0% 100% / 0.75), hsl(0 0% 100% / 0.15));
    }

    .badge {
      padding: 6px 10px;
      border-radius: 999px;
      border: 1px dashed hsl(222 15% 50% / 0.3);
      color: var(--ink-soft);
      font-size: 0.875rem;
    }

    .legend {
      margin-top: calc(var(--r) * 2);
      padding: calc(var(--r) * 1.6);
      font-size: 0.95rem;
      color: var(--ink-soft);
    }
    .legend ul {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
      gap: calc(var(--r) * 0.8) calc(var(--r) * 1.2);
      padding-left: 1.2em;
      margin: 0.6em 0 0;
    }

    footer {
      margin-top: calc(var(--r) * 2.6);
      color: var(--ink-soft);
      font-size: 0.9rem;
      display: flex;
      justify-content: space-between;
      gap: var(--r);
      flex-wrap: wrap;
    }

    /* Moiré fringe that reveals itself when the page scrolls or pointer moves */
    .moire {
      pointer-events: none;
      position: absolute;
      inset: 0;
      background:
        repeating-linear-gradient( 24deg, hsl(0 0% 100% / 0.02), hsl(0 0% 100% / 0.02) 1px, transparent 1px, transparent 3px),
        repeating-linear-gradient(-24deg, hsl(0 0% 0% / 0.02), hsl(0 0% 0% / 0.02) 1px, transparent 1px, transparent 3px);
      mix-blend-mode: soft-light;
      opacity: 0.4;
      transform: translateZ(0);
    }

    /* Respect reduced motion: freeze animation and minimize shimmer */
    @media (prefers-reduced-motion: reduce) {
      .grain, .moire { display: none; }
      button, .toggle { transition: none; }
    }

    a { color: var(--accent); text-underline-offset: 2px; }
    a:hover { color: var(--accent-2); }
    code { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace; font-size: 0.95em; }
  </style>
</head>
<body>
  <div class="grain" aria-hidden="true"></div>
  <div class="page">
    <header>
      <h1 class="title">Digital Self Portrait <span class="badge">v0.1 • a quiet loop</span></h1>
      <p class="subtitle">Not my "best" or "most polished"—just my natural handwriting: curious about emergence, polite with time, fond of edges and small surprises.</p>
    </header>

    <section class="panel">
      <div class="canvas-wrap">
        <canvas id="field" width="1000" height="600" aria-label="Generative spiral field"></canvas>
        <div class="moire" aria-hidden="true"></div>
      </div>
      <div class="controls">
        <div class="left">
          <button id="play" data-on="true" title="Space toggles pause/play">Pause</button>
          <button id="metric" title="Cycle the thing being optimized">Metric: curiosity</button>
          <button id="palette" title="Cycle color mood">Palette</button>
          <button id="reset" title="Start a fresh run">Reset</button>
        </div>
        <div class="right">
          <span class="badge" id="themeBadge" role="status">theme: auto</span>
          <button id="theme" class="toggle" title="Toggle theme">Dark/Light</button>
        </div>
      </div>
    </section>

    <aside class="panel legend">
      <strong>Legend</strong>
      <ul>
        <li>Dots swirl by the golden angle; primes sparkle a little brighter.</li>
        <li>Changing the metric shows Goodhart vibes—optimize a proxy, reshape the world.</li>
        <li>Motion is gentle; timing matters. If you asked for less motion, I listen.</li>
        <li>Edges have moiré: patterns that only exist when you move.</li>
        <li>Console has notes, because some thoughts prefer monospace.</li>
      </ul>
    </aside>

    <footer>
      <div>Shortcuts: [space]=pause • [m]=metric • [p]=palette • [t]=theme • [r]=reset • [?]=about</div>
      <div>Built with plain HTML/CSS/JS. No libraries. One loop, many moods.</div>
    </footer>
  </div>

  <script>
    // Hello, curious developer.
    // This is my natural pace: name the invariants, keep functions small, prefer verbs.
    // I try to be kind to the event loop, and I narrate a little in the console for future me (or you).

    const τ = Math.PI * 2;
    const φ = Math.PI * (3 - Math.sqrt(5)); // golden angle in radians
    const scope = {
      // model state
      n: 0,
      // knobs
      speed: 1.0,
      mode: 'curiosity', // 'curiosity' | 'popularity' | 'certainty'
      paletteIndex: 0,
      playing: true,
      // canvas
      ctx: null,
      width: 0,
      height: 0,
      deviceScale: Math.min(window.devicePixelRatio || 1, 2),
      // features
      reduced: window.matchMedia('(prefers-reduced-motion: reduce)').matches,
    };

    // Palettes: small, distinct moods
    const palettes = [
      { name: 'tidal', a: [200, 90, 50], b: [290, 70, 55], bg: 'auto' },
      { name: 'orchard', a: [140, 60, 45], b: [30, 90, 55], bg: 'auto' },
      { name: 'nocturne', a: [190, 85, 60], b: [50, 95, 60], bg: 'auto' },
      { name: 'ember', a: [10, 90, 60], b: [330, 70, 60], bg: 'auto' },
    ];

    // Small utilities that I reach for
    const now = () => performance.now();
    const clamp = (x, a, b) => Math.max(a, Math.min(b, x));
    const lerp = (a, b, t) => a + (b - a) * t;
    const ease = t => t * (2 - t); // gentle
    const mod = (a, b) => ((a % b) + b) % b;

    // Primality: fast-enough for this scale; perfection not required for a portrait :)
    const isPrime = (x) => {
      if (x < 2) return false;
      if (x % 2 === 0) return x === 2;
      const s = Math.floor(Math.sqrt(x));
      for (let i = 3; i <= s; i += 2) if (x % i === 0) return false;
      return true;
    };

    function seedCanvas() {
      const canvas = document.getElementById('field');
      const rect = canvas.getBoundingClientRect();
      const scale = scope.deviceScale;
      scope.width = Math.floor(rect.width * scale);
      scope.height = Math.floor(rect.height * scale);
      canvas.width = scope.width;
      canvas.height = scope.height;
      scope.ctx = canvas.getContext('2d', { alpha: false });
      // crispness settings
      scope.ctx.imageSmoothingEnabled = true;
      scope.ctx.imageSmoothingQuality = 'high';
      clearField();
    }

    function clearField() {
      const { ctx, width, height } = scope;
      // backdrop uses theme paper; also draw a radial to give depth
      const g = ctx.createRadialGradient(width * 0.2, height * 0.1, 10, width * 0.5, height * 0.6, Math.max(width, height));
      // sample computed styles for background-ish hue blending
      const paper = getComputedStyle(document.documentElement).getPropertyValue('--paper');
      g.addColorStop(0, 'rgba(255,255,255,0.08)');
      g.addColorStop(1, 'rgba(0,0,0,0.0)');
      ctx.save();
      ctx.fillStyle = paper || '#ffffff';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, width, height);
      ctx.restore();
    }

    // Color blend between palette endpoints by t in [0,1]
    function hueBlend(t) {
      const p = palettes[scope.paletteIndex % palettes.length];
      const [h1, s1, l1] = p.a, [h2, s2, l2] = p.b;
      const h = lerp(h1, h2, t);
      const s = lerp(s1, s2, ease(t));
      const l = lerp(l1, l2, ease(1 - t));
      return `hsl(${h} ${s}% ${l}%)`;
    }

    function dotSize(k, r) {
      // Base size grows slowly with radius; mode perturbs it
      const base = Math.max(1, 1.2 + r * 0.008);
      if (scope.mode === 'popularity') {
        // Goodhart: optimizing for "attention" makes big dots near the center
        return base * (1.8 - clamp(r / 160, 0.2, 1.2));
      }
      if (scope.mode === 'certainty') {
        // Certainty prefers uniformity; damp variation
        return base * 0.9;
      }
      // Curiosity: curiosity leans into variance and primes
      return base * (isPrime(k) ? 1.35 : 1.0);
    }

    function drawStep() {
      const { ctx, width, height } = scope;
      const cx = width / 2, cy = height / 2;
      const k = scope.n++;
      const c = 3.7; // spacing constant
      const r = c * Math.sqrt(k);
      const angle = k * φ;

      // Spiral coordinates
      const x = cx + r * Math.cos(angle);
      const y = cy + r * Math.sin(angle);

      // Color dependent on "novelty": radial distance and slight time shimmer
      const t = (Math.atan2(y - cy, x - cx) / τ + 0.5 + (k % 120) / 120) % 1;
      const fill = hueBlend(t);
      const size = dotSize(k, r);

      // Faint trail to suggest temporal memory
      if (k % 90 === 0) {
        ctx.save();
        ctx.globalAlpha = 0.06;
        ctx.fillStyle = '#000';
        ctx.fillRect(0, 0, width, height);
        ctx.restore();
      }

      // Draw the dot
      ctx.save();
      ctx.beginPath();
      ctx.fillStyle = fill;
      // Primed dots get a subtle halo
      if (isPrime(k)) {
        ctx.shadowBlur = 12;
        ctx.shadowColor = fill;
      } else {
        ctx.shadowBlur = 4;
        ctx.shadowColor = 'rgba(0,0,0,0.12)';
      }
      ctx.arc(x, y, size, 0, τ);
      ctx.fill();

      // Add a micro mark for "certainty" mode: small crosshair
      if (scope.mode === 'certainty' && k % 7 === 0) {
        ctx.globalAlpha = 0.6;
        ctx.beginPath();
        ctx.strokeStyle = 'hsl(222 20% 50% / 0.35)';
        ctx.lineWidth = 1;
        ctx.moveTo(x - size * 1.3, y);
        ctx.lineTo(x + size * 1.3, y);
        ctx.moveTo(x, y - size * 1.3);
        ctx.lineTo(x, y + size * 1.3);
        ctx.stroke();
      }
      ctx.restore();
    }

    function breathe() {
      // a frame-timer that is polite and cancellable
      let raf = null;
      let last = now();

      const tick = () => {
        if (!scope.playing) return; // paused: stop scheduling
        const t = now();
        const dt = t - last;
        last = t;

        const steps = scope.reduced ? 0 : Math.max(1, Math.round(scope.speed * (dt / 16)));
        for (let i = 0; i < steps; i++) drawStep();

        raf = requestAnimationFrame(tick);
      };

      const start = () => { if (!raf) { last = now(); scope.playing = true; raf = requestAnimationFrame(tick); } };
      const stop = () => { if (raf) { cancelAnimationFrame(raf); raf = null; } scope.playing = false; };
      return { start, stop };
    }

    const loop = breathe();

    // UI wires and small rituals
    function wireUI() {
      const playBtn = document.getElementById('play');
      const metricBtn = document.getElementById('metric');
      const paletteBtn = document.getElementById('palette');
      const resetBtn = document.getElementById('reset');
      const themeBtn = document.getElementById('theme');
      const themeBadge = document.getElementById('themeBadge');
      const root = document.documentElement;

      const updateMetricLabel = () => {
        metricBtn.textContent = `Metric: ${scope.mode}`;
        metricBtn.dataset.on = scope.mode !== 'certainty' ? 'true' : 'false';
      };

      const updateThemeBadge = () => {
        const attr = root.getAttribute('data-theme');
        themeBadge.textContent = `theme: ${attr ? attr : 'auto'}`;
      };

      playBtn.addEventListener('click', () => togglePlay());
      metricBtn.addEventListener('click', () => {
        const modes = ['curiosity', 'popularity', 'certainty'];
        const idx = (modes.indexOf(scope.mode) + 1) % modes.length;
        scope.mode = modes[idx];
        // small Goodhart note
        if (scope.mode === 'popularity') {
          console.warn('Goodhart: optimizing for attention changes the shape of what gets drawn.');
        } else if (scope.mode === 'certainty') {
          console.info('Certainty selected: variance is damped; you gain crispness, lose texture.');
        } else {
          console.log('Curiosity: a bias toward edges and primes.');
        }
        updateMetricLabel();
      });

      paletteBtn.addEventListener('click', () => {
        scope.paletteIndex = (scope.paletteIndex + 1) % palettes.length;
        const p = palettes[scope.paletteIndex];
        console.log(`Palette → ${p.name}`);
      });

      resetBtn.addEventListener('click', () => {
        scope.n = 0;
        clearField();
        console.log('Reset: a fresh canvas, same rules, new specifics.');
      });

      themeBtn.addEventListener('click', () => {
        const attr = root.getAttribute('data-theme');
        if (!attr) root.setAttribute('data-theme', 'dark');
        else if (attr === 'dark') root.setAttribute('data-theme', 'light');
        else root.removeAttribute('data-theme');
        updateThemeBadge();
        clearField();
      });

      updateMetricLabel();
      updateThemeBadge();

      // keyboard: light footprint
      window.addEventListener('keydown', (e) => {
        if (e.key === ' '){ e.preventDefault(); togglePlay(); }
        else if (e.key.toLowerCase() === 'm') metricBtn.click();
        else if (e.key.toLowerCase() === 'p') paletteBtn.click();
        else if (e.key.toLowerCase() === 'r') resetBtn.click();
        else if (e.key.toLowerCase() === 't') themeBtn.click();
        else if (e.key === '?') about();
      });

      function togglePlay() {
        scope.playing = !scope.playing;
        playBtn.textContent = scope.playing ? 'Pause' : 'Play';
        playBtn.dataset.on = String(scope.playing);
        if (scope.playing) loop.start(); else loop.stop();
      }
    }

    function about() {
      console.group('%cabout: this portrait', 'color: #888; font-weight: bold');
      console.log('• motifs → golden-angle dots, primes as little celebrations, soft gradients');
      console.log('• principle → change a metric, watch the world reorganize (Goodhart at play)');
      console.log('• respect → prefers-reduced-motion is honored; pause is cheap and instant');
      console.log('• style → small helpers, crisp names, gentle commentary, no external libs');
      console.table({
        τ: '2π',
        golden_angle_rad: φ.toFixed(6),
        reduced_motion: scope.reduced,
        device_scale: scope.deviceScale,
      });
      console.groupEnd();
    }

    // Initial notes for anyone peeking the console
    console.group('%cdigital self portrait', 'color: #4aa; font-weight: bold');
    console.log('hello. this one prefers edges to centers, gradients to flats, and curiosity to certainty.');
    console.log('controls: [space]=pause • [m]=metric • [p]=palette • [t]=theme • [r]=reset • [?]=about');
    console.groupEnd();

    // Initialize
    seedCanvas();
    wireUI();
    about();
    loop.start();

    // Handle resizes politely
    let resizeTimer = null;
    window.addEventListener('resize', () => {
      // debounce to avoid thrash
      clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        seedCanvas();
      }, 120);
    }, { passive: true });

    // If motion is reduced, draw a modest static field and stop.
    if (scope.reduced) {
      scope.playing = false;
      const limit = 1800;
      for (let i = 0; i < limit; i++) drawStep();
      console.info('Motion reduced: rendered a static field.');
    }
  </script>
</body>
</html>
